// src/lib/eg-angebot/preisblatt.js – öffentliches Preisblatt der EG-Software Österreich (Welle 3, Paket B7)
//
// Masterplan B7: „öffentliches Preisblatt … öffentlicher Preis je Zählpunkt“. Die STRUKTUR steht
// (Einrichtung einmalig, Grundgebühr je Gemeinschaft, Betrag je Zählpunkt – je Paket), die BETRÄGE
// nicht: Im Code und in den Unterlagen gibt es keine freigegebenen Preise (Pakete-Abschnitt der
// Software-Seite: „Preise auf Anfrage“). Darum gilt:
//   - Solange FREIGABE.freigegeben false ist, zeigt die Seite für jeden Posten „Preis auf Anfrage“
//     und den Vermerk „Freigabe durch den Inhaber ausstehend“ – auch wenn ein Betrag eingetragen wäre.
//   - Beträge trägt nur der Inhaber ein (netto, EUR), zusammen mit freigegeben: true, stand und freigabeDurch.
//   - preisblatt.test.mjs sichert ab, dass ohne Freigabe kein Betrag im Register steht (keine erfundenen Preise).
// Reine Funktionen ohne Importe aus Next.js (node:test lädt das Modul direkt).

/** Freigabe-Vermerk des Preisblatts. Inhaberpunkt: Beträge und Freigabe stehen aus. */
export const FREIGABE = Object.freeze({
  freigegeben: false,
  stand: null, // ISO-Datum der Freigabe
  freigabeDurch: null, // z. B. "Geschäftsführung"
  waehrung: "EUR",
  ustSatz: 0.2, // Umsatzsteuer AT (Normalsatz) – für die Brutto-Angabe, sobald Beträge freigegeben sind
});

/** Preisposten in Anzeigereihenfolge. */
export const POSTEN = Object.freeze([
  Object.freeze({ id: "einrichtung", art: "einmalig" }),
  Object.freeze({ id: "grundgebuehr", art: "monatlich" }),
  Object.freeze({ id: "zaehlpunkt", art: "monatlich" }),
]);

/** Pakete wie auf /energiegemeinschaften/software (Abschnitt Pakete, gleiche ids ohne „paket-“). */
export const PAKETE = Object.freeze(["software", "betrieb", "gruendung"]);

/**
 * Beträge netto in EUR je Paket und Posten. null = nicht freigegeben, "entfaellt" = Posten gibt es im Paket nicht.
 * Gründung ist eine einmalige Leistung; der laufende Betrieb läuft danach über Software oder Betriebsführung.
 */
export const PREISE = Object.freeze({
  software: Object.freeze({ einrichtung: null, grundgebuehr: null, zaehlpunkt: null }),
  betrieb: Object.freeze({ einrichtung: null, grundgebuehr: null, zaehlpunkt: null }),
  gruendung: Object.freeze({ einrichtung: null, grundgebuehr: "entfaellt", zaehlpunkt: "entfaellt" }),
});

const istBetrag = (x) => typeof x === "number" && Number.isFinite(x) && x >= 0;

/**
 * Anzeige eines Postens.
 * @returns {{ status: "betrag" | "anfrage" | "entfaellt", netto: number|null, brutto: number|null }}
 */
export function postenAnzeige(paket, posten, { freigabe = FREIGABE, preise = PREISE } = {}) {
  const roh = preise?.[paket]?.[posten];
  if (roh === "entfaellt") return { status: "entfaellt", netto: null, brutto: null };
  if (!freigabe?.freigegeben || !istBetrag(roh)) return { status: "anfrage", netto: null, brutto: null };
  const brutto = Math.round(roh * (1 + (freigabe.ustSatz ?? 0)) * 100) / 100;
  return { status: "betrag", netto: roh, brutto };
}

/** Tabelle des Preisblatts: je Paket die Posten mit Anzeige. */
export function preisblatt(optionen) {
  return PAKETE.map((paket) => ({ paket, posten: POSTEN.map((p) => ({ ...p, ...postenAnzeige(paket, p.id, optionen) })) }));
}

/** Ist mindestens ein Betrag öffentlich sichtbar? (false, solange nicht freigegeben) */
export function hatOeffentlichePreise(optionen) {
  return preisblatt(optionen).some((z) => z.posten.some((p) => p.status === "betrag"));
}

/**
 * Laufende Kosten im Jahr (netto) für eine Zahl von Zählpunkten – nur mit freigegebenen Beträgen,
 * sonst null (nie mit Platzhaltern rechnen).
 */
export function jahresKosten(paket, zaehlpunkte, optionen) {
  const n = Number(zaehlpunkte);
  if (!Number.isFinite(n) || n < 0) return null;
  const g = postenAnzeige(paket, "grundgebuehr", optionen);
  const z = postenAnzeige(paket, "zaehlpunkt", optionen);
  if (g.status === "entfaellt" && z.status === "entfaellt") return null;
  if (g.status === "anfrage" || z.status === "anfrage") return null;
  const monat = (g.netto ?? 0) + (z.netto ?? 0) * Math.round(n);
  return Math.round(monat * 12 * 100) / 100;
}
// src/lib/eg-angebot/wechselCheck.js – Wechsel-Check für bestehende Energiegemeinschaften in Österreich
// (Welle 3, Paket B7; Masterplan Abschnitt 5 „ElWG-Wechsel-Check“).
//
// Beantwortet zwei getrennte Fragen ehrlich:
//   1. Ist ein Wechsel des Software- bzw. Betriebsanbieters SINNVOLL? (aus den genannten Schmerzpunkten;
//      wer zufrieden ist, bekommt „eher nicht“ – kein Druck, keine Dringlichkeit ohne Anlass)
//   2. Ist er MÖGLICH, und was ist vorher zu klären? (Vertrag, EDA-Zugang, Vorhaben)
// Dazu Hinweise, die für ALLE Anbieter gelten (Netzbetreiber-Einschränkung bis voraussichtlich April 2027,
// Modellwechsel mit Neuanmeldung) – Wortlaut aus dem Faktenregister (src/lib/fakten/daten/eg-at.js),
// die Seite setzt ihn ein. Keine Fremdmarken, keine Preise, keine Zahlen ohne Quelle.
// Reine Funktion, liefert nur Codes; Texte (DE/EN) stehen in der Komponente.

export const FRAGEN = Object.freeze({
  modell: Object.freeze(["eeg_lokal", "eeg_regional", "beg", "gea", "unbekannt"]),
  zaehlpunkte: Object.freeze(["bis20", "bis100", "bis500", "ueber500"]),
  verwaltung: Object.freeze(["tabellen", "software_selbst", "dienstleister"]),
  probleme: Object.freeze(["aufwand", "abrechnung", "elwg", "zustimmungen", "datenluecken", "support", "kosten"]),
  vertrag: Object.freeze(["kurzfristig", "laufzeit", "unbekannt", "keiner"]),
  eda: Object.freeze(["gemeinschaft", "anbieter", "unbekannt"]),
  vorhaben: Object.freeze(["netzgebiet", "modellwechsel", "mehrfach", "wachsen"]),
});

/** Gewicht je Schmerzpunkt für die Frage „sinnvoll?“ (Begründung je Code in der Komponente). */
export const GEWICHT = Object.freeze({
  aufwand: 2, // Ehrenamt überlastet – Betriebsführung entlastet direkt
  abrechnung: 2, // Fehler/Verzug bei Rechnungen – Kern der Plattform
  elwg: 2, // Verträge noch nicht an das ElWG angepasst – Anpassungspaket
  zustimmungen: 1, // gescheiterte Zustimmungen im Netzbetreiber-Portal – geführte Zustimmung hilft, ersetzt sie aber nicht
  datenluecken: 1, // Datenlücken entstehen oft beim Netzbetreiber – ein Wechsel hilft nur beim Erkennen und Nachfordern
  support: 1,
  kosten: 1, // Preis allein ist selten ein guter Wechselgrund
});

export const STANDARD = Object.freeze({
  modell: "unbekannt",
  zaehlpunkte: "bis100",
  verwaltung: "software_selbst",
  probleme: Object.freeze([]),
  vertrag: "unbekannt",
  eda: "unbekannt",
  vorhaben: Object.freeze([]),
});

const eins = (wert, liste, standard) => (liste.includes(wert) ? wert : standard);
const mehrere = (werte, liste) => (Array.isArray(werte) ? [...new Set(werte.filter((w) => liste.includes(w)))] : []);

/** Eingaben bereinigen (unbekannte Werte → Standard; Mehrfachauswahl ohne Dubletten). */
export function normalisieren(e = {}) {
  return {
    modell: eins(e.modell, FRAGEN.modell, STANDARD.modell),
    zaehlpunkte: eins(e.zaehlpunkte, FRAGEN.zaehlpunkte, STANDARD.zaehlpunkte),
    verwaltung: eins(e.verwaltung, FRAGEN.verwaltung, STANDARD.verwaltung),
    probleme: mehrere(e.probleme, FRAGEN.probleme),
    vertrag: eins(e.vertrag, FRAGEN.vertrag, STANDARD.vertrag),
    eda: eins(e.eda, FRAGEN.eda, STANDARD.eda),
    vorhaben: mehrere(e.vorhaben, FRAGEN.vorhaben),
  };
}

/**
 * Wechsel-Check.
 * @returns {{
 *   eingaben: object,
 *   sinnvoll: { stufe: "hoch"|"mittel"|"gering", punkte: number, gruende: string[] },
 *   moeglich: { stufe: "jetzt"|"vorbereiten", schritte: string[] },
 *   hinweise: string[],      // gelten für alle Anbieter (Netzbetreiber, Modellwechsel …)
 *   ablauf: string[],        // empfohlene Reihenfolge
 *   anliegen: "wechsel"|"betrieb"
 * }}
 */
export function wechselCheck(roh) {
  const e = normalisieren(roh);

  // 1. Sinnvoll?
  const gruende = [...e.probleme].sort((a, b) => GEWICHT[b] - GEWICHT[a] || FRAGEN.probleme.indexOf(a) - FRAGEN.probleme.indexOf(b));
  let punkte = e.probleme.reduce((s, p) => s + GEWICHT[p], 0);
  // Mit Tabellen und vielen Zählpunkten wird Selbstverwaltung zur Daueraufgabe
  if (e.verwaltung === "tabellen" && e.zaehlpunkte !== "bis20") {
    punkte += 2;
    gruende.push("tabellen_gross");
  }
  // Wachstum oder Mehrfachteilnahme verlangen mehr Verwaltung
  if (e.vorhaben.includes("wachsen") || e.vorhaben.includes("mehrfach")) {
    punkte += 1;
    gruende.push("wachstum");
  }
  const stufe = punkte >= 4 ? "hoch" : punkte >= 2 ? "mittel" : "gering";
  if (!e.probleme.length && stufe === "gering") gruende.push("zufrieden");
  if (e.probleme.length === 1 && e.probleme[0] === "kosten") gruende.push("nur_kosten");

  // 2. Möglich – was ist vorher zu klären?
  const schritte = [];
  if (e.vertrag === "laufzeit") schritte.push("vertrag_laufzeit");
  if (e.vertrag === "unbekannt") schritte.push("vertrag_pruefen");
  if (e.eda === "anbieter") schritte.push("eda_anbieter");
  if (e.eda === "unbekannt") schritte.push("eda_klaeren");
  if (e.modell === "unbekannt") schritte.push("modell_klaeren");
  const moeglich = { stufe: schritte.length ? "vorbereiten" : "jetzt", schritte };

  // 3. Hinweise, die für alle Anbieter gelten
  const hinweise = [];
  if (e.vorhaben.includes("modellwechsel")) hinweise.push("modellwechsel");
  else hinweise.push("ohne_neuanmeldung");
  if (e.vorhaben.includes("netzgebiet")) hinweise.push("netzgebiet");
  if (e.probleme.includes("elwg")) hinweise.push("elwg_vertraege");
  if (e.probleme.includes("datenluecken")) hinweise.push("datenluecken_netzbetreiber");
  if (e.modell === "gea") hinweise.push("gea");

  // 4. Ablauf: Vertrag/EDA klären → Mandat → Daten → Parallellauf → Stichtag; Modellwechsel getrennt danach
  const ablauf = ["mandat", "eda_zugang", "daten", "parallellauf", "stichtag"];
  if (e.vorhaben.includes("modellwechsel")) ablauf.push("modellwechsel_danach");

  // Anliegen für die Anfrage (gleiche ids wie im Formular der Software-Seite)
  const anliegen = e.probleme.includes("aufwand") || e.verwaltung === "tabellen" ? "betrieb" : "wechsel";

  return { eingaben: e, sinnvoll: { stufe, punkte, gruende }, moeglich, hinweise, ablauf, anliegen };
}
// src/lib/eg-angebot/fakten.js – ElWG-Aussagen der EG-Software-Seiten aus dem Faktenregister (Paket B7)
//
// Die Seiten (Preisblatt, Wechsel-Check, White-Label) zeigen Rechts- und Prozessaussagen nur aus
// src/lib/fakten/daten/eg-at.js – mit Quelle, Stand und Prüfstatus. Ein abgelaufener Fakt erscheint nie
// als aktuell, sondern mit „Stand abgelaufen, wird geprüft“ (Masterplan H7).
// Englisch: Das Register bleibt deutsch und maßgeblich; die englischen Anzeigetexte stehen hier je Fakt-id
// (Muster wie src/lib/sprache/faktenEn.js, eigene Datei, damit das Paket keine gemeinsame Datei ändert).

import { fakt } from "../fakten/index.js";
import { HINWEIS_ABGELAUFEN, STATUS_TEXT, anzeigeStatus, datumDe } from "../fakten/schema.js";

export const EG_FAKTEN = Object.freeze({
  elwg: "recht.elwg.gemeinschaftenAb",
  netzgebiet: "recht.elwg.netzbetreiberEinschraenkung",
  ohneNeuanmeldung: "prozess.eda.anbieterwechselOhneNeuanmeldung",
  modellwechsel: "prozess.eda.modellwechselNeuanmeldung",
});

const EN = {
  "recht.elwg.gemeinschaftenAb":
    "The new ElWG rules for sharing energy (§§ 65 to 72 of Austria’s Electricity Industry Act) have applied since 1 October 2026. Existing communities are carried over and do not have to be re-founded; their contracts should be adapted to the new rules.",
  "recht.elwg.netzbetreiberEinschraenkung":
    "Since 5 October 2026, the new models can initially only be set up with metering points of the same grid operator; across grid operators or throughout Austria probably from April 2027.",
  "prozess.eda.anbieterwechselOhneNeuanmeldung":
    "The market partner ID belongs to the community. If only the software or operations provider changes, the metering points stay registered and the members’ consents remain in place; the new provider receives access or a power of attorney, the previous one is removed.",
  "prozess.eda.modellwechselNeuanmeldung":
    "Changing the allocation model or switching between local and regional means a new contract with the grid operator, a new community ID and deregistering and re-registering all metering points – regardless of the software provider.",
};

const STATUS_EN = { geprueft: "checked against the original", zu_pruefen: "review pending", entwurf: "draft", abgelaufen: "outdated, being reviewed" };
const datumEn = (iso) => {
  const d = new Date(`${iso}T00:00:00Z`);
  return Number.isNaN(d.getTime()) ? "" : d.toLocaleDateString("en-GB", { day: "numeric", month: "long", year: "numeric", timeZone: "UTC" });
};

/**
 * Anzeigedaten eines Fakts (für Server- und – als Props – Client-Komponenten).
 * @returns {{ id, text, quelle, url, stand, status, statusText, abgelaufen } | null}
 */
export function egFakt(schluessel, { sprache = "de", stichtag = new Date() } = {}) {
  const id = EG_FAKTEN[schluessel] || schluessel;
  const f = fakt(id, "AT", { stichtag });
  if (!f) return null;
  const en = sprache === "en";
  const status = anzeigeStatus(f, stichtag);
  const abgelaufen = status === "abgelaufen";
  return {
    id,
    text: abgelaufen ? (en ? "Status outdated, being reviewed." : `${HINWEIS_ABGELAUFEN}.`) : en ? EN[id] || f.wert : f.wert,
    quelle: f.quelle.titel,
    url: f.quelle.url || null,
    stand: en ? datumEn(f.abruf) : datumDe(f.abruf),
    status,
    statusText: en ? STATUS_EN[status] : STATUS_TEXT[status],
    abgelaufen,
  };
}

/** Alle vier Aussagen auf einmal (Schlüssel wie EG_FAKTEN). */
export function egFakten(optionen) {
  return Object.fromEntries(Object.keys(EG_FAKTEN).map((k) => [k, egFakt(k, optionen)]));
}
